<script setup lang="ts">import {ref} from 'vue';import * as api from '../api/datasets';import * as dictionaries from '../api/dictionaries';import {useResource} from '../hooks/useResource';import {refreshResources} from '../stores/resources';import {user} from '../stores/session';import PageTitle from '../components/common/PageTitle.vue';import Notice from '../components/common/Notice.vue';const{data,error}=useResource(api.list,[]),{data:dicts}=useResource(dictionaries.list,[]);const name=ref('补充匿名观展路径'),dictionary=ref('dict-gallery'),source=ref('gallery_paths_202611.csv'),csv=ref(''),message=ref('');async function submit(){try{await api.create({name:name.value,dictionary_id:dictionary.value,source:source.value,csv_text:csv.value});csv.value='';message.value='';refreshResources()}catch(e:any){message.value=e.message}}async function upload(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(f){if(f.size>1000000){message.value='CSV不能超过1MB';return}source.value=f.name;csv.value=await f.text()}}</script><template><PageTitle chapter="02" title="一条旅程，只记一份支持" description="只接收匿名journey_id。路径触点用 > 分隔，终态converted或exited；空路径、未知触点与重复ID拒绝。"/><Notice :error="error||message"/><section class="paper table-scroll"><table><thead><tr><th>路径数据</th><th>旅程数</th><th>转化 / 退出</th></tr></thead><tbody><tr v-for="d in data" :key="d.id"><td><b>{{d.name}}</b><small>{{d.source}}</small></td><td>{{d.row_count}}</td><td>{{d.converted}} / {{d.exited}}</td></tr></tbody></table></section><form v-if="user?.role!=='viewer'" class="paper form-grid" @submit.prevent="submit"><label>数据集名称<input v-model="name"/></label><label>编码册<select v-model="dictionary"><option v-for="d in dicts" :key="d.id" :value="d.id">{{d.name}}</option></select></label><label>CSV文件<input type="file" accept=".csv" @change="upload"/></label><label class="wide">路径内容<textarea v-model="csv" placeholder="journey_id,path,outcome"/></label><button class="primary">校验并导入旅程</button></form></template>
